const loadDay=async date=>{const r=++dayRequest;selectedDate=date;selectedTime='';dateInput.value=date;timeInput.value='';$('[data-slot-area]').hidden=false;setText('[data-slot-description]',`Waktu kedatangan untuk ${formatDate(date)}.`);setStatus('[data-slot-status]','Memuat slot waktu…');try{const res=await fetch(`${availabilityUrl}?date=${date}&jenis_servis_id=${selectedService}`,{headers:{Accept:'application/json'}});if(!res.ok)throw Error();const data=await res.json();if(r!==dayRequest)return;daySlots=data.slots||[];renderSlots();renderCalendar();updateSummary();gate()}catch(_){setStatus('[data-slot-status]','Slot belum dapat dimuat.',true)}};
const techInitials=n=>(n||'YZA').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase(),techLabels={available:'Tersedia',assigned:'Sedang Bertugas',time_off:'Tidak Bertugas',unavailable:'Tidak Tersedia'};const renderTech=(rows,message='Pilih teknisi atau lanjutkan tanpa preferensi.')=>{const g=$('[data-personnel-grid]');g.innerHTML='';const none=document.createElement('button');none.type='button';none.className=`personnel-card ${!selectedTechnician?'is-selected':''}`;none.innerHTML='<span class="personnel-avatar">—</span><strong class="personnel-name">Tidak Ada Preferensi</strong><span class="personnel-title">YZA menentukan teknisi sesuai ketersediaan.</span>';none.onclick=()=>{selectedTechnician=null;techInput.value='';renderTech(rows);updateSummary()};g.append(none);rows.forEach(x=>{const b=document.createElement('button');b.type='button';b.className=`personnel-card ${selectedTechnician?.id===x.id?'is-selected':''}`;b.disabled=!x.available;b.innerHTML=`<span class="personnel-avatar">${techInitials(x.display_name)}</span><strong class="personnel-name">${x.display_name}</strong><span class="personnel-title">${x.title||''}</span><span class="personnel-meta">${techLabels[x.availability_status]||x.availability_status}</span>`;if(x.available)b.onclick=()=>{selectedTechnician=x;techInput.value=x.id;renderTech(rows);updateSummary()};g.append(b)});setText('[data-personnel-message]',message)};
const loadTechnicians=async()=>{if(!selectedService||!selectedDate||!selectedTime)return;const r=++techRequest;if(techController)techController.abort();techController=new AbortController();renderTech([],'Memuat teknisi tersedia...');try{const res=await fetch(`${technicianUrl}?date=${selectedDate}&time=${selectedTime}&jenis_servis_id=${selectedService}`,{headers:{Accept:'application/json'},signal:techController.signal});const data=await res.json();if(r===techRequest)renderTech(data.technicians||[])}catch(e){if(e.name!=='AbortError')renderTech([],'Tidak ada preferensi teknisi.')}};
const collapsed=()=>{const v=vehicle(),t=service(),f=finish();setText('[data-collapsed-schedule-main]',`${v?.name||'Kendaraan belum dipilih'} · ${t?.name||'Servis belum dipilih'}`);setText('[data-collapsed-schedule-meta]',`${formatDate(selectedDate)} · ${selectedTime?`${selectedTime} – ${f||'—'} WIB`:'Waktu belum dipilih'}`);setText('[data-collapsed-complaint]',$('#booking-complaint')?.value||'-');setText('[data-collapsed-note]',$('#booking-note')?.value||'-')};
const setStep=n=>{if(n===2&&!valid())return;if(n===3&&!valid())return;step=n;$$('[data-panel]').forEach(p=>p.hidden=+p.dataset.panel!==step);$('[data-collapsed-schedule]').hidden=step===1;$('[data-collapsed-detail]').hidden=step<3;$$('[data-step-button]').forEach(b=>{const no=+b.dataset.stepButton;b.classList.toggle('is-active',no===step);b.classList.toggle('is-complete',no<step);b.disabled=no>step;b.toggleAttribute('aria-current',no===step);});collapsed();updateSummary();window.scrollTo({top:root.offsetTop-16,behavior:'smooth'})};
vehicleSelect?.addEventListener('change',e=>{vehicleInput.value=e.target.value;updateSummary();gate()});$$('[data-service-choice]').forEach(b=>b.onclick=()=>{selectedService=b.dataset.serviceChoice;serviceInput.value=selectedService;selectedDate='';selectedTime='';dateInput.value='';timeInput.value='';selectedTechnician=null;techInput.value='';$$('[data-service-choice]').forEach(x=>x.classList.toggle('is-selected',x===b));$('[data-slot-area]').hidden=true;updateSummary();gate();loadMonth()});$('[data-month-prev]')?.addEventListener('click',()=>{if(month<=root.dataset.currentMonth)return;const[y,m]=month.split('-').map(Number),d=new Date(y,m-2,1);month=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;loadMonth()});$('[data-month-next]')?.addEventListener('click',()=>{const[y,m]=month.split('-').map(Number),d=new Date(y,m,1);month=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;loadMonth()});$$('[data-next-step],[data-prev-step]').forEach(b=>b.onclick=()=>setStep(+(b.dataset.nextStep||b.dataset.prevStep)));$('[data-edit-schedule]')?.addEventListener('click',()=>setStep(1));$('[data-edit-detail]')?.addEventListener('click',()=>setStep(2));['booking-complaint','booking-note'].forEach(id=>$('#'+id)?.addEventListener('input',()=>{updateSummary();collapsed()}));dateInput.value=selectedDate;timeInput.value=selectedTime;updateSummary();gate();if(selectedService)loadMonth();else renderCalendar()})();
</script>
@endpush
